rows[71550]={title={{13,837500609},"천상의 보호막"},description={"^protects the paladin from all damage and spells for ([%+%-]?%d[%d,.]* %a+), but reduces all damage you deal by ([%+%-]?%d[%d,.%+%-to –]*)%%%. once protected, the target cannot be protected by divine shield, divine protection or hand of protection again for ([%+%-]?%d[%d,.]* %a+)%. cannot be used within ([%+%-]?%d[%d,.]* %a+)%. of using avenging wrath%.$","\0311\031 동안 모든 공격과 주문으로부터 자신을 보호하지만 공격력이 \0312\031%만큼 감소합니다. 한 번 보호한 후 \0313\031 동안은 천상의 보호막, 신의 가호, 보호의 손길로 보호받지 못합니다. 응징의 격노 사용 후 \0314\031 동안은 사용하지 못합니다.",{1,0,1,1},{1,2,3,4}},aura={"^immune to all attacks and spells, but reduces all damage you deal by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","모든 공격 및 주문에 면역\010공격력 \0311\031%만큼 감소",{0},{1}}}
