rows[71554]={title={{12,367669838},"방어구 가르기"},description={"^sunders the target's armor, reducing it by ([%+%-]?%d[%d,.%+%-to –]*)%% per sunder armor and causes a high amount of threat%. threat increased by attack power%. can be applied up to 5 times%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","적의 방어구를 손상시켜 방어구 가르기 효과 하나당 방어도를 \0311\031%만큼 감소시킵니다. 위협 수준이 크게 증가합니다. 전투력에 따라 위협 수준이 증가합니다. 최대 5번까지 중복될 수 있습니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^armor decreased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","방어도 \0311\031%만큼 감소",{0},{1}}}
