rows[71780]={title={{18,25209197},"신의 권능: 보호막"},description={"^draws on the soul of the party member to shield them, absorbing ([%+%-]?%d[%d,.%+%-to –]*) damage%. lasts ([%+%-]?%d[%d,.]* %a+)%. while the shield holds, spellcasting will not be interrupted by damage%. once shielded, the target cannot be shielded again for ([%+%-]?%d[%d,.]* %a+)%.$","파티원의 영적인 힘을 이용하여 즉시 보호막을 생성하여 \0311\031의 피해를 흡수합니다. \0312\031 동안 지속됩니다. 보호막이 지속되는 동안은 피해에 의해 주문 시전이 방해받지 않습니다. 한 번 보호막을 사용한 대상에겐 \0313\031 동안 다시 보호막을 사용할 수 없습니다.",{0,1,1},{1,2,3}},aura={{15,1513431201},"피해 흡수"}}
