rows[71785]={title={{13,75225301},"거대한 불길"},description={"^sets an enemy aflame, inflicting ([%+%-]?%d[%d,.%+%-to –]*) fire damage over ([%+%-]?%d[%d,.]* %a+)%. and sending it into a state of panic%. while the target is affected, the flames periodically scorch its nearby allies for ([%+%-]?%d[%d,.%+%-to –]*) damage as well%.$","적을 불태워 \0312\031에 걸쳐 총 \0311\031의 화염 피해를 입히고 공황 상태에 빠뜨립니다. 불타는 동안 대상의 주변 아군도 주기적으로 \0313\031의 피해를 입습니다.",{0,1,0},{1,2,3}},aura={{15,1460989398},"불타는 중"}}
rows[71786]={title={{13,2063398465},"로켓 발사"},description={"^fire a powerful rocket at the enemy that does ([%+%-]?%d[%d,.%+%-to –]*) damage and stuns them for ([%+%-]?%d[%d,.%+%-to –]*) sec%. this thing has quite a kick though%.%.%.$","강력한 로켓탄을 적에게 발사하여 \0311\031의 피해를 입히고 \0312\031초 동안 기절시킵니다. 반동이 대단하니 조심해서 사용하십시오.",{0,0},{1,2}},aura={{8,318235535},"기절함"}}
