rows[73681]={title={{12,79651532},"바람 폭발"},description={"^unleashes the windfury enchantment upon the shaman's weapon, dealing ([%+%-]?%d[%d,.%+%-to –]*)%% of weapon damage to the target enemy and increasing the shaman's melee attack speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for the next 6 swings or until ([%+%-]?%d[%d,.]* %a+) have elapsed%.$","주술사의 무기에 부여한 질풍의 무기 효과를 폭발시킵니다. 적 대상에게 무기 공격력의 \0311\031%에 해당하는 피해를 입히고, \0313\031 동안 또는 다음 6회의 공격 동안 주술사의 근접 공격 속도가 \0312\031%만큼 증가합니다.",{0,0,1},{1,2,3}},aura={"^melee attack speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","근접 공격 속도 \0311\031%만큼 증가",{0},{1}}}
rows[73682]={title={{13,1153136802},"냉기 폭발"},description={"^unleashes the frostbrand enchantment upon the shaman's weapon, dealing ([%+%-]?%d[%d,.%+%-to –]*) frost damage to a target enemy and reducing their movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. increased in effectiveness if the target is already afflicted by a movement%-slowing frost effect%.$","주술사의 무기에 부여한 냉기의 무기 효과를 폭발시킵니다. 적에게 \0311\031의 냉기 피해를 입히고, \0313\031 동안 대상의 이동 속도를 \0312\031%만큼 감소시킵니다. 대상에게 이미 냉기 계열 감속 효과가 걸려 있다면 효과가 증가합니다.",{0,0,1},{1,2,3}},aura={"^movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소",{0},{1}}}
rows[73683]={title={{13,1139407201},"불꽃 폭발"},description={"^unleashes the flametongue enchantment upon the shaman's weapon, dealing ([%+%-]?%d[%d,.%+%-to –]*) fire damage to target enemy and increasing the damage dealt by the shaman's next fire spell by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","주술사의 무기에 부여한 불꽃의 무기 효과를 폭발시킵니다. 적에게 \0311\031의 화염 피해를 입히고, 다음에 사용하는 화염 계열 주문의 공격력이 \0312\031%만큼 증가합니다.",{0,0},{1,2}},aura={"^damage dealt by the next fire spell increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","다음 화염 계열 주문의 공격력 \0311\031%만큼 증가",{0},{1}}}
rows[73684]={title={{13,820470936},"대지 폭발"},description={"^unleashes the rockbiter enchantment upon the shaman's weapon, forcing the target enemy to attack the shaman, and increasing threat that you generate against the target by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","주술사의 무기에 부여한 대지의 무기 효과를 폭발시켜 적이 주술사를 공격하도록 만듭니다. 또한 적과 맞설 때 생성되는 위협 수준이 \0312\031 동안 \0311\031%만큼 증가합니다.",{0,1},{1,2}},aura={{8,569239999},"도발당함"}}
rows[73685]={title={{12,54921484},"생명 폭발"},description={"^unleashes the earthliving enchantment upon the shaman's weapon, healing a friendly target for ([%+%-]?%d[%d,.%+%-to –]*) and increasing the effect of the shaman's next direct heal or healing rain by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","주술사의 무기에 부여한 대지생명의 무기 효과를 폭발시킵니다. 아군 대상의 생명력을 \0311\031만큼 회복시키고 주술사가 다음에 시전하는 직접 치유 주문 또는 치유의 비 효과가 \0312\031%만큼 증가합니다.",{0,0},{1,2}},aura={"^your next direct heal or healing rain will be ([%+%-]?%d[%d,.%+%-to –]*)%% more effective%.$","다음 직접 치유 주문 또는 치유의 비 효과 \0311\031%만큼 증가",{0},{1}}}
