rows[74502]={title={{16,368778496},"무력의 낙인"},description={"^brands an enemy target, siphoning power from the target and any allies within ([%+%-]?%d[%d,.%+%-to –]*) yards of the target%. this effect occurs every ([%+%-]?%d[%d,.%+%-to –]*) sec, and reduces affected enemies' damage by ([%+%-]?%d[%d,.%+%-to –]*)%% per application, while increasing the caster's damage accordingly%.$","적에게 낙인을 찍어 대상과 그로부터 \0311\031미터 반경 내에 있는 모든 적의 힘을 흡수합니다. \0312\031초마다 효과가 발생하며 효과 하나당 적의 공격력을 \0313\031%만큼 감소시키고 시전자의 공격력은 그만큼 증가시킵니다.",{0,0,0},{1,2,3}},aura={"^weakens you and nearby allies every ([%+%-]?%d[%d,.%+%-to –]*) sec, reducing damage and healing done by ([%+%-]?%d[%d,.%+%-to –]*)%% per application%.$","\0311\031초마다 자신과 주변 아군 약화\010효과 하나당 공격력 및 치유량 \0312\031%만큼 감소",{0,0},{1,2}}}
