rows[75683]={title={{10,1372354159},"용오름"},description={"^creates a whirling vortex of water, periodically knocking back enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%. in addition, the whirling water will deflect any spells cast at the caster and cause all ranged attacks to miss%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","휘몰아치는 물 소용돌이를 생성하여, 반경 \0311\031미터 내에 있는 적을 주기적으로 밀쳐냅니다. 추가로, 휘몰아치는 물은 시전자를 대상으로 시전한 모든 주문을 튕겨내고 모든 원거리 공격이 빗나가게 합니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^knocks back nearby enemies%. increases chance to deflect spells by ([%+%-]?%d[%d,.%+%-to –]*)%%%. increases chance for ranged attacks to miss by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","주위 적을 튕겨냄\010주문 튕겨낼 확률 \0311\031%만큼 증가\010원거리 공격에 적중당하지 않을 확률 \0312\031%만큼 증가",{0,0},{1,2}}}
