rows[76613]={title={{16,2090439065},"특화: 고드름"},description={"^when you damage enemies with frostbolt and frostfire bolt, ([%+%-]?%d[%d,.%+%-to –]*)%% of the damage done is stored as an icicle with you, for ([%+%-]?%d[%d,.]* %a+)%. also increases the damage of your water elemental's waterbolt by ([%+%-]?%d[%d,.%+%-to –]*)%%%. up to ([%+%-]?%d[%d,.%+%-to –]*) icicles can be stored at once%. casting ice lance causes any icicles to begin launching at the target%.$","얼음 화살과 얼음불꽃 화살로 적에게 피해를 줄 때, \0312\031 동안 피해의 \0311\031%가 고드름으로 저장됩니다. 또한 물의 정령이 사용하는 물화살의 공격력이 \0313\031% 증가합니다.\010\010동시에 최대 \0314\031개의 고드름을 저장할 수 있습니다. 얼음창을 시전하면 모든 고드름이 대상을 향해 날아갑니다.",{0,1,0,0},{1,2,3,4}}}
rows[76615]={title={{12,1073658765},"꽁꽁 얼리기"},description={"^stuns an enemy and inflicts frost damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031 동안 적을 기절시키고 \0311\031초마다 냉기 피해를 입힙니다.",{0,1},{1,2}},aura={"^stunned%. ([%+%-]?%d[%d,.%+%-to –]*) frost damage inflicted every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","기절함\010\0312\031초마다 \0311\031의 냉기 피해",{0,0},{1,2}}}
