rows[76617]={title={{15,840183927},"열기 피로"},description={"^the extreme heat exhausts targets in a large area, reducing maximum health by ([%+%-]?%d[%d,.%+%-to –]*)%% and movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%%%. stacks%.$","극도의 고열로 넓은 지역의 대상을 지치게 만들어 최대 생명력을 \0311\031%만큼, 이동 속도를 \0312\031%만큼 감소시킵니다. 중복됩니다.",{0,0},{1,2}},aura={"^maximum health decreased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. movement speed decreased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","최대 생명력 \0311\031%만큼 감소\010이동 속도 \0312\031%만큼 감소",{0,0},{1,2}}}
